"""Path resolution and string interpolation for workflow execution."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path

from ..quest_service import FatalInvariantError
from ..quest_types import QuestMeta, utc_now_iso
from ..workflow_config import WorkflowCollection, WorkflowDefinition
from .workflow_state_io import WorkflowStateIo

_PATH_VARS = ("quest", "project", "machine", "active_child")
_BRACE_RE = re.compile(r"\{([a-zA-Z_][a-zA-Z0-9_]*)\}")


def path_matches_collection_pattern(rel_path: str, pattern: str) -> bool:
    pattern_parts = pattern.split("/")
    path_parts = rel_path.split("/")
    if len(pattern_parts) != len(path_parts):
        return False
    for pattern_part, path_part in zip(pattern_parts, path_parts):
        if pattern_part == "*":
            continue
        if pattern_part != path_part:
            return False
    return True


def list_collection_children(
    collection: WorkflowCollection,
    quest_dir: Path,
) -> list[tuple[str, Path]]:
    prefix = collection.path.split("*")[0].rstrip("/")
    base = quest_dir / prefix if prefix else quest_dir
    if not base.is_dir():
        return []
    children: list[tuple[str, Path]] = []
    for child_dir in base.iterdir():
        if not child_dir.is_dir():
            continue
        rel = child_dir.resolve().relative_to(quest_dir.resolve()).as_posix()
        if path_matches_collection_pattern(rel, collection.path):
            children.append((child_dir.name, child_dir.resolve()))
    if collection.order == "lexical":
        children.sort(key=lambda item: item[0])
    return children


def collection_child_dir(
    collection: WorkflowCollection,
    quest_dir: Path,
    child_id: str,
) -> Path:
    prefix = collection.path.split("*")[0].rstrip("/")
    if prefix:
        return (quest_dir / prefix / child_id).resolve()
    return (quest_dir / child_id).resolve()


@dataclass
class WorkflowPathContext:
    repo_path: Path
    quest_dir: Path
    machine_dir: Path
    machine_key: str
    workflow: WorkflowDefinition
    workflow_io: WorkflowStateIo
    meta: QuestMeta
    persisted_tags: dict[str, str] = field(default_factory=dict)
    step_vars: dict[str, str] = field(default_factory=dict)

    def project_dir(self) -> Path:
        return (self.repo_path / "projects" / self.meta.project).resolve()

    def active_child_dir(self) -> Path | None:
        for collection in self.workflow.collections.values():
            active_id = self.persisted_tags.get(collection.active_var, "").strip()
            if not active_id:
                continue
            child_dir = collection_child_dir(collection, self.quest_dir, active_id)
            if child_dir.is_dir():
                return child_dir
        return None

    def var_value(self, name: str) -> str | None:
        if name in self.step_vars:
            return self.step_vars[name]
        if name in self.persisted_tags:
            return self.persisted_tags[name]
        return None

    def interpolate_string(self, text: str) -> str:
        def replace(match: re.Match[str]) -> str:
            key = match.group(1)
            if key == "now":
                return utc_now_iso()
            value = self.var_value(key)
            if value is None:
                raise FatalInvariantError(
                    f"Unknown workflow variable {key!r} in interpolation"
                )
            return value

        return _BRACE_RE.sub(replace, text)


def _split_path_variable(path_value: str) -> tuple[str | None, str]:
    if not path_value.startswith("$"):
        return None, path_value
    remainder = path_value[1:]
    for var_name in _PATH_VARS:
        if remainder == var_name:
            return var_name, ""
        prefix = f"{var_name}/"
        if remainder.startswith(prefix):
            return var_name, remainder[len(prefix) :]
    raise FatalInvariantError(f"Unknown path variable in {path_value!r}")


def _resolve_path_variable(var_name: str, ctx: WorkflowPathContext) -> Path:
    if var_name == "quest":
        return ctx.quest_dir.resolve()
    if var_name == "project":
        return ctx.project_dir()
    if var_name == "machine":
        return ctx.machine_dir.resolve()
    if var_name == "active_child":
        active = ctx.active_child_dir()
        if active is None:
            raise FatalInvariantError(
                "Cannot resolve $active_child: no active child directory"
            )
        return active
    raise FatalInvariantError(f"Unknown path variable {var_name!r}")


def assert_quest_relative_path(path_value: str, *, label: str) -> None:
    if Path(path_value).is_absolute():
        raise FatalInvariantError(
            f"{label}: absolute paths are not allowed for workflow-owned paths: "
            f"{path_value!r}"
        )


def resolve_path(path_value: str, ctx: WorkflowPathContext) -> Path:
    interpolated = ctx.interpolate_string(path_value)
    assert_quest_relative_path(interpolated, label="path")
    var_name, remainder = _split_path_variable(interpolated)
    if var_name is not None:
        base = _resolve_path_variable(var_name, ctx)
        if not remainder:
            return base
        return (base / remainder).resolve()
    return (ctx.machine_dir / interpolated).resolve()

"""Workflow condition evaluation."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .. import quest_fs
from ..quest_service import FatalInvariantError
from .workflow_paths import (
    WorkflowPathContext,
    list_collection_children,
    resolve_path,
)


@dataclass(frozen=True)
class ChildStepResult:
    state_after: str


def evaluate_condition(
    condition: Any,
    ctx: WorkflowPathContext,
    *,
    child_result: ChildStepResult | None = None,
) -> bool:
    if not isinstance(condition, dict):
        raise FatalInvariantError(f"Condition must be a mapping, got {type(condition).__name__}")
    if "all" in condition:
        items = condition["all"]
        if not isinstance(items, list):
            raise FatalInvariantError("Condition 'all' must be a list")
        return all(evaluate_condition(item, ctx, child_result=child_result) for item in items)
    if "any" in condition:
        items = condition["any"]
        if not isinstance(items, list):
            raise FatalInvariantError("Condition 'any' must be a list")
        return any(evaluate_condition(item, ctx, child_result=child_result) for item in items)
    if "not" in condition:
        return not evaluate_condition(
            condition["not"], ctx, child_result=child_result
        )
    for key in ("exists", "file_exists", "dir_exists", "not_exists"):
        if key in condition:
            path_value = condition[key]
            if not isinstance(path_value, str):
                raise FatalInvariantError(f"Condition {key!r} requires a string path")
            target = resolve_path(path_value, ctx)
            exists = target.exists()
            if key == "exists":
                return exists
            if key == "not_exists":
                return not exists
            if key == "file_exists":
                return target.is_file()
            if key == "dir_exists":
                return target.is_dir()
    if "file_count_at_least" in condition:
        block = condition["file_count_at_least"]
        if not isinstance(block, dict):
            raise FatalInvariantError("file_count_at_least must be a mapping")
        glob_value = block.get("glob")
        count_value = block.get("count")
        if not isinstance(glob_value, str):
            raise FatalInvariantError("file_count_at_least.glob must be a string")
        if not isinstance(count_value, int) or isinstance(count_value, bool):
            raise FatalInvariantError("file_count_at_least.count must be an integer")
        base = ctx.machine_dir
        matches = list(base.glob(glob_value))
        return len(matches) >= count_value
    for issue_key in ("has_open_issues", "no_open_issues"):
        if issue_key in condition:
            block = condition[issue_key]
            if not isinstance(block, dict):
                raise FatalInvariantError(f"{issue_key} must be a mapping")
            file_value = block.get("file")
            if not isinstance(file_value, str):
                raise FatalInvariantError(f"{issue_key}.file must be a string")
            issue_path = resolve_path(file_value, ctx)
            open_issues = _has_open_issues(issue_path)
            if issue_key == "has_open_issues":
                return open_issues
            return not open_issues
    if "var_exists" in condition:
        name = condition["var_exists"]
        if not isinstance(name, str):
            raise FatalInvariantError("var_exists must be a string")
        return ctx.var_value(name) is not None
    if "var_equals" in condition:
        block = condition["var_equals"]
        if not isinstance(block, dict):
            raise FatalInvariantError("var_equals must be a mapping")
        name = block.get("name")
        value = block.get("value")
        if not isinstance(name, str) or not isinstance(value, str):
            raise FatalInvariantError("var_equals requires string name and value")
        current = ctx.var_value(name)
        return current == value
    if "child_dirs_exist" in condition:
        block = condition["child_dirs_exist"]
        if not isinstance(block, dict):
            raise FatalInvariantError("child_dirs_exist must be a mapping")
        collection_name = block.get("collection")
        collection = _get_collection(ctx, collection_name)
        return bool(list_collection_children(collection, ctx.quest_dir))
    if "all_children" in condition:
        block = condition["all_children"]
        if not isinstance(block, dict):
            raise FatalInvariantError("all_children must be a mapping")
        collection_name = block.get("collection")
        require = block.get("require", [])
        if not isinstance(require, list):
            raise FatalInvariantError("all_children.require must be a list")
        collection = _get_collection(ctx, collection_name)
        children = list_collection_children(collection, ctx.quest_dir)
        if not children:
            return False
        for _, child_dir in children:
            child_ctx = _child_path_context(ctx, child_dir)
            for requirement in require:
                if not _evaluate_child_requirement(requirement, child_ctx):
                    return False
        return True
    if "child_result" in condition:
        if child_result is None:
            raise FatalInvariantError(
                "child_result condition requires a child step result from the current state"
            )
        block = condition["child_result"]
        if not isinstance(block, dict):
            raise FatalInvariantError("child_result must be a mapping")
        expected = block.get("state_after")
        if not isinstance(expected, str):
            raise FatalInvariantError("child_result.state_after must be a string")
        return child_result.state_after == expected
    raise FatalInvariantError(f"Unknown condition: {condition!r}")


def _has_open_issues(issue_path: Path) -> bool:
    issues = quest_fs.read_issues(issue_path)
    return any(issue.status.strip().lower() == "open" for issue in issues)


def _get_collection(ctx: WorkflowPathContext, collection_name: Any):
    if not isinstance(collection_name, str):
        raise FatalInvariantError("collection name must be a string")
    try:
        return ctx.workflow.collections[collection_name]
    except KeyError as e:
        raise FatalInvariantError(
            f"Unknown workflow collection {collection_name!r}"
        ) from e


def _child_path_context(ctx: WorkflowPathContext, child_dir: Path) -> WorkflowPathContext:
    return WorkflowPathContext(
        repo_path=ctx.repo_path,
        quest_dir=ctx.quest_dir,
        machine_dir=child_dir,
        machine_key=ctx.machine_key,
        workflow=ctx.workflow,
        workflow_io=ctx.workflow_io,
        meta=ctx.meta,
        persisted_tags=dict(ctx.persisted_tags),
        step_vars=dict(ctx.step_vars),
    )


def _evaluate_child_requirement(requirement: Any, child_ctx: WorkflowPathContext) -> bool:
    if not isinstance(requirement, dict):
        raise FatalInvariantError("all_children requirement must be a mapping")
    if "file_count_at_least" in requirement:
        block = requirement["file_count_at_least"]
        if not isinstance(block, dict):
            raise FatalInvariantError("file_count_at_least must be a mapping")
        glob_value = block.get("glob")
        count_value = block.get("count")
        if not isinstance(glob_value, str):
            raise FatalInvariantError("file_count_at_least.glob must be a string")
        if not isinstance(count_value, int) or isinstance(count_value, bool):
            raise FatalInvariantError("file_count_at_least.count must be an integer")
        matches = list(child_ctx.machine_dir.glob(glob_value))
        return len(matches) >= count_value
    for key in ("exists", "file_exists", "dir_exists", "not_exists"):
        if key in requirement:
            path_value = requirement[key]
            if not isinstance(path_value, str):
                raise FatalInvariantError(f"Requirement {key!r} requires a string path")
            target = resolve_path(path_value, child_ctx)
            exists = target.exists()
            if key == "exists":
                return exists
            if key == "not_exists":
                return not exists
            if key == "file_exists":
                return target.is_file()
            if key == "dir_exists":
                return target.is_dir()
    return evaluate_condition(requirement, child_ctx)

"""Workflow action execution."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from ..quest_service import FatalInvariantError
from .workflow_paths import (
    WorkflowPathContext,
    collection_child_dir,
    list_collection_children,
    resolve_path,
)


def execute_actions(actions: list[Any], ctx: WorkflowPathContext) -> None:
    for action in actions:
        execute_action(action, ctx)


def execute_action(action: Any, ctx: WorkflowPathContext) -> None:
    if isinstance(action, str):
        raise FatalInvariantError(f"Unsupported bare action string: {action!r}")
    if not isinstance(action, dict):
        raise FatalInvariantError(f"Action must be a mapping, got {type(action).__name__}")
    if "ensure_dir" in action:
        path_value = action["ensure_dir"]
        if not isinstance(path_value, str):
            raise FatalInvariantError("ensure_dir requires a string path")
        resolve_path(path_value, ctx).mkdir(parents=True, exist_ok=True)
        return
    if "ensure_file" in action:
        block = action["ensure_file"]
        if not isinstance(block, dict):
            raise FatalInvariantError("ensure_file must be a mapping")
        path_value = block.get("path")
        content = block.get("content", "")
        if not isinstance(path_value, str):
            raise FatalInvariantError("ensure_file.path must be a string")
        if not isinstance(content, str):
            raise FatalInvariantError("ensure_file.content must be a string")
        target = resolve_path(path_value, ctx)
        if not target.exists():
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(ctx.interpolate_string(content), encoding="utf-8")
        return
    if "remove_file" in action:
        path_value = action["remove_file"]
        if not isinstance(path_value, str):
            raise FatalInvariantError("remove_file requires a string path")
        target = resolve_path(path_value, ctx)
        if target.exists():
            target.unlink()
        return
    if "set_var" in action:
        block = action["set_var"]
        if not isinstance(block, dict):
            raise FatalInvariantError("set_var must be a mapping")
        name = block.get("name")
        value = block.get("value")
        if not isinstance(name, str) or not isinstance(value, str):
            raise FatalInvariantError("set_var requires string name and value")
        ctx.persisted_tags[name] = ctx.interpolate_string(value)
        return
    if "clear_var" in action:
        name = action["clear_var"]
        if not isinstance(name, str):
            raise FatalInvariantError("clear_var requires a string name")
        ctx.persisted_tags.pop(name, None)
        return
    if "select_child" in action:
        _execute_select_child(action["select_child"], ctx)
        return
    raise FatalInvariantError(f"Unknown action: {action!r}")


def _execute_select_child(block: Any, ctx: WorkflowPathContext) -> None:
    if not isinstance(block, dict):
        raise FatalInvariantError("select_child must be a mapping")
    collection_name = block.get("collection")
    where = block.get("where", {})
    after_var = block.get("after")
    set_var = block.get("set")
    result_var = block.get("result")
    if not isinstance(collection_name, str):
        raise FatalInvariantError("select_child.collection must be a string")
    if not isinstance(where, dict):
        raise FatalInvariantError("select_child.where must be a mapping")
    if not isinstance(set_var, str):
        raise FatalInvariantError("select_child.set must be a string")
    if not isinstance(result_var, str):
        raise FatalInvariantError("select_child.result must be a string")
    try:
        collection = ctx.workflow.collections[collection_name]
    except KeyError as e:
        raise FatalInvariantError(
            f"Unknown workflow collection {collection_name!r}"
        ) from e
    children = list_collection_children(collection, ctx.quest_dir)
    matching: list[tuple[str, Path]] = []
    for child_id, child_dir in children:
        logical_state = ctx.workflow_io.ReadStateMachineState(child_dir).state
        if _child_matches_where(logical_state, where):
            matching.append((child_id, child_dir))
    if not matching:
        return
    after_id: str | None = None
    if isinstance(after_var, str):
        after_value = ctx.var_value(after_var)
        if after_value:
            child_ids = {child_id for child_id, _ in children}
            if after_value in child_ids:
                after_id = after_value
    selected: tuple[str, Path] | None = None
    if after_id is None:
        selected = matching[0]
    else:
        child_order = [child_id for child_id, _ in children]
        try:
            after_index = child_order.index(after_id)
        except ValueError:
            selected = matching[0]
        else:
            for child_id, child_dir in matching:
                if child_order.index(child_id) > after_index:
                    selected = (child_id, child_dir)
                    break
    if selected is None:
        return
    child_id, _ = selected
    _ = collection_child_dir(collection, ctx.quest_dir, child_id)
    ctx.persisted_tags[set_var] = child_id
    ctx.step_vars[result_var] = child_id


def _child_matches_where(logical_state: str, where: dict[str, Any]) -> bool:
    state_is = where.get("state_is")
    state_not = where.get("state_not")
    if state_is is not None:
        if not isinstance(state_is, str):
            raise FatalInvariantError("select_child.where.state_is must be a string")
        return logical_state == state_is
    if state_not is not None:
        if not isinstance(state_not, str):
            raise FatalInvariantError("select_child.where.state_not must be a string")
        return logical_state != state_not
    raise FatalInvariantError("select_child.where requires state_is or state_not")

"""Workflow-aware quest and child machine state I/O."""

from __future__ import annotations

from pathlib import Path
from typing import Mapping

from .. import quest_fs
from ..quest_service import FatalInvariantError
from ..quest_types import (
    QuestMeta,
    RecursiveSnapshot,
    StateMachineState,
    slice_index_from_dirname,
)
from ..workflow_config import WorkflowCollection, WorkflowDefinition, WorkflowState

_IDENTITY_TAGS = frozenset({"quest_type", "quest_number", "quest_slug"})
_RESERVED_TOP_LEVEL_PERSISTED = frozenset({"ExperimentComplete"})
_NORMALIZED_STATE_HEADING = "# State"


def _path_matches_collection_pattern(rel_path: str, pattern: str) -> bool:
    pattern_parts = pattern.split("/")
    path_parts = rel_path.split("/")
    if len(pattern_parts) != len(path_parts):
        return False
    for pattern_part, path_part in zip(pattern_parts, path_parts):
        if pattern_part == "*":
            continue
        if pattern_part != path_part:
            return False
    return True


class WorkflowStateIo:
    """``StateIo`` that reads and writes state via workflow machine definitions."""

    def __init__(
        self,
        repo_path: Path,
        quest_dir: Path,
        meta: QuestMeta,
        workflow: WorkflowDefinition,
    ) -> None:
        self.repo_path = repo_path.resolve()
        self.quest_dir = quest_dir.resolve()
        self.meta = meta
        self.workflow = workflow

    def ReadStateMachineState(self, state_machine_dir: Path) -> StateMachineState:
        machine_dir = state_machine_dir.resolve()
        machine_key = self._machine_key_for_dir(machine_dir)
        if machine_key == self.workflow.entry_machine:
            return self._read_quest(machine_key)
        return self._read_child(machine_key, machine_dir)

    def WriteStateMachineState(
        self, state_machine_dir: Path, state: StateMachineState
    ) -> None:
        machine_dir = state_machine_dir.resolve()
        machine_key = self._machine_key_for_dir(machine_dir)
        if machine_key == self.workflow.entry_machine:
            self._write_quest(machine_key, state)
        else:
            self._write_child(machine_key, machine_dir, state)

    def logical_state_for_persisted(
        self, machine_key: str, persisted_state: str
    ) -> str:
        if (
            machine_key == self.workflow.entry_machine
            and persisted_state in _RESERVED_TOP_LEVEL_PERSISTED
        ):
            return persisted_state
        machine = self.workflow.get_machine(machine_key)
        for state_def in machine.states.values():
            if state_def.persisted_as == persisted_state:
                return state_def.name
        if persisted_state in machine.states:
            return persisted_state
        raise FatalInvariantError(
            f"Persisted state {persisted_state!r} is not declared for machine "
            f"{machine_key!r}"
        )

    def persisted_state_for_logical(self, machine_key: str, logical_state: str) -> str:
        if (
            machine_key == self.workflow.entry_machine
            and logical_state in _RESERVED_TOP_LEVEL_PERSISTED
        ):
            return logical_state
        machine = self.workflow.get_machine(machine_key)
        state_def = machine.states.get(logical_state)
        if state_def is None:
            raise FatalInvariantError(
                f"Logical state {logical_state!r} is not declared for machine "
                f"{machine_key!r}"
            )
        if state_def.persisted_as is not None:
            return state_def.persisted_as
        return logical_state

    def machine_name_for_instance(self, machine_key: str, machine_dir: Path) -> str:
        machine = self.workflow.get_machine(machine_key)
        if machine_dir.resolve() == self.quest_dir:
            return machine.machine
        return f"{machine.machine}_{machine_dir.name}"

    def machine_path_for_instance(self, machine_dir: Path) -> str:
        return machine_dir.resolve().relative_to(self.repo_path).as_posix()

    def machine_key_for_dir(self, machine_dir: Path) -> str:
        return self._machine_key_for_dir(machine_dir)

    def _machine_key_for_dir(self, machine_dir: Path) -> str:
        if machine_dir.resolve() == self.quest_dir:
            return self.workflow.entry_machine
        collection = self._collection_for_dir(machine_dir)
        if collection is not None:
            return collection.machine
        raise FatalInvariantError(
            f"Directory {machine_dir} does not match any workflow collection"
        )

    def _collection_for_dir(self, machine_dir: Path) -> WorkflowCollection | None:
        if machine_dir.resolve() == self.quest_dir:
            return None
        rel = machine_dir.resolve().relative_to(self.quest_dir).as_posix()
        for collection in self.workflow.collections.values():
            if _path_matches_collection_pattern(rel, collection.path):
                return collection
        return None

    def _read_quest(self, machine_key: str) -> StateMachineState:
        path = self.quest_dir / "state.md"
        text = path.read_text(encoding="utf-8")
        first: str | None = None
        for ln in text.splitlines():
            s = ln.strip()
            if not s:
                continue
            first = s
            break
        if first == _NORMALIZED_STATE_HEADING:
            sm = quest_fs.parse_normalized_state_md_text(
                text,
                require_global_step=False,
                label=f"normalized quest state file {path}",
            )
            logical = self.logical_state_for_persisted(machine_key, sm.state)
            g = sm.global_step if sm.global_step is not None else 0
            return StateMachineState(
                machine_name=sm.machine_name,
                machine_path=sm.machine_path,
                state=logical,
                global_step=g,
                tags=dict(sm.tags),
                updated_at=sm.updated_at,
            )
        info = quest_fs.read_quest_state(self.quest_dir)
        logical = self.logical_state_for_persisted(machine_key, info.state.value)
        rel = self.quest_dir.relative_to(self.repo_path).as_posix()
        tags: dict[str, str] = {}
        if info.active_slice:
            tags["active_slice"] = info.active_slice
        return StateMachineState(
            machine_name=self.workflow.get_machine(machine_key).machine,
            machine_path=rel,
            state=logical,
            global_step=info.global_step if info.global_step is not None else 0,
            tags=tags,
            updated_at=info.updated_at,
        )

    def _read_child(self, machine_key: str, machine_dir: Path) -> StateMachineState:
        persisted, updated_at = quest_fs.read_slice_persisted_state(machine_dir)
        logical = self.logical_state_for_persisted(machine_key, persisted)
        return StateMachineState(
            machine_name=self.machine_name_for_instance(machine_key, machine_dir),
            machine_path=self.machine_path_for_instance(machine_dir),
            state=logical,
            global_step=None,
            tags={},
            updated_at=updated_at,
        )

    def _write_quest(self, machine_key: str, sm: StateMachineState) -> None:
        persisted = self.persisted_state_for_logical(machine_key, sm.state)
        gs = sm.global_step if sm.global_step is not None else 0
        tags: dict[str, str] = {
            "quest_type": self.meta.quest_type,
            "quest_number": str(self.meta.quest_number),
            "quest_slug": self.meta.quest_slug,
        }
        for key, value in sm.tags.items():
            if key not in _IDENTITY_TAGS:
                tags[key] = value
        rel = self.quest_dir.relative_to(self.repo_path).as_posix()
        out = StateMachineState(
            machine_name=self.workflow.get_machine(machine_key).machine,
            machine_path=rel,
            state=persisted,
            global_step=gs,
            tags=tags,
            updated_at=sm.updated_at,
        )
        quest_fs.write_normalized_machine_state(self.quest_dir, out)

    def _write_child(
        self, machine_key: str, machine_dir: Path, sm: StateMachineState
    ) -> None:
        persisted = self.persisted_state_for_logical(machine_key, sm.state)
        quest_fs.write_slice_persisted_state(
            machine_dir,
            persisted_state=persisted,
            updated_at=sm.updated_at,
        )


def build_workflow_step_snapshot(
    *,
    workflow_io: WorkflowStateIo,
    machine_key: str,
    machine_dir: Path,
    workflow_state: WorkflowState,
    state_before: str,
    state_after: str,
    tags: Mapping[str, str],
    child: RecursiveSnapshot | None = None,
) -> RecursiveSnapshot:
    """Build a recursive snapshot from execution-local workflow step data."""
    node_name = (
        workflow_state.node_name
        if workflow_state.node_name is not None
        else workflow_state.name
    )
    return RecursiveSnapshot(
        machine_path=workflow_io.machine_path_for_instance(machine_dir),
        machine_name=workflow_io.machine_name_for_instance(machine_key, machine_dir),
        node_name=node_name,
        state_before=state_before,
        state_after=state_after,
        tags=dict(tags),
        child=child,
    )
